 save('render-inspection.json',{'passed':True,'actual_ui_previews':11,'automated_reports':['render/rendering.json','render-remaining/rendering.json'],'visually_inspected':['render/question-001.png','render/question-002.png','render/question-003.png','render/question-004.png','render/question-005.png','render-remaining/question-002.png','render-remaining/question-004.png','render-remaining/question-005.png'],'observations':['Controlled same-A pair displays different target matrix, selected operation and final solution: R3:=R3-2R1 versus R3:=1/5 R3. Both alter only R3, defeating a changed-row-only shortcut.','Irrelevant-row edit changes a first-row entry in both matrices (5 to 6), while scaling R3 by 1/5 remains correct.','Matrices have three visible rows and columns, scalable brackets, and legible negative signs and fractions. Five radio choices display without exposed TeX.','Swap bank shows two non-elementary distractors without promoting them to valid targets.','No overlap or missing mathematical content observed in inspected prompts or worked solutions.','All five runner batch records rendered; representative addition and scale screenshots visually inspected.'],'renderer_limit':'First invocation rendered default six; second invocation rendered the remaining five, without rerendering completed previews.'})
 roles=[]
 for role,eligible,observed in [('Operation family','Swap, scale, row addition; never a non-elementary replacement','All three in audit; exact five-record batch has 3 additions and 2 scales.'),('Qualifying bank choice','Every lesson-defined elementary operation in each complete source bank','48/48 eligible choices observed across ten banks before and after actual delivery; q-72850 has three swaps and two ineligible replacements.'),('Source/destination row or swapped pair','All three row identities via simultaneous row permutations','Domain contains all six permutations for every bank; samples exercise changed rows 1, 2 and 3 and swap pairs.'),('Scalar','Source-bank nonzero simple integer or rational multipliers','Positive and negative integer/fraction coefficients are present. They are derived from offered source choices, rather than independently unbounded coefficients.'),('Correct displayed position','Any radio position; no canonical correct position','Authored correct keys vary within every bank; actual UI hash ordering and item-ID scenarios tested. Exact batch uses authored slots 1,3,4,5.')]:roles.append({'role':role,'eligible_variation':eligible,'observed':observed})
 probes=load(E/'shortcut-results.json')['controlled_probes']+load(E/'action-shortcut-results.json')['conditional_action_probes']
 batch=load(E/'batch-delivery/accepted.json')
 probes.append({'cue':'Authored slot 3','subgroup':'exact five-record runner batch','scope':'overall','strategy':'Always choose third authored option','correct':sum(key(r)==2 for r in batch),'total':5,'baseline':.2,'disposition':'not_predictive','conclusion':'2/5 versus uniform five-choice guessing at 0.2; fails on three members. Bank-only best fitted fixed-choice rule succeeds 4/5, because the repeated q-130087 bank has two different qualifying choices. UI additionally reorders choices by item and answer IDs. No universal incidental action was demonstrated on this batch.','sample_refs':['batch-delivery/accepted.json','action-shortcut-results.json']})
 pedagogy={'learner_operation':'Compare the two matrices row by row; identify the changed row(s), distinguish scaling/addition/swapping, and verify which offered operation reproduces every affected entry.','fixed_features':[{'feature':'One operation on ordinary 3×3 matrices, one five-choice radio field','justification':'All twelve captured question banks use this structure; canonical example and lesson assess a single elementary operation rather than elimination or system solving.'},{'feature':'A single valid offered answer; nonzero scale and distinct addition rows','justification':'Radio response contract and tutorial 3150’s elementary-operation definitions.'},{'feature':'Complete observed bank profiles and their small coefficients; bounded single-entry matrix perturbations','justification':'Keeps source distractors and comparable arithmetic workload. Fixed source signs and zero locations are conservative domain limits, not mathematical invariants; they do not fix the answer because all 48 eligible bank choices are exercised with identical A within each panel.'}],'answer_roles':roles,'coverage':[{'case':'Complete source banks','sample_refs':['source-replays.json','source-replay-results.json'],'result':'10 exact prompts/solutions/banks, 50 choices. Two incomplete unrated captures have no authored replay certification.'},{'case':'Within-bank alternative targets at fixed A','sample_refs':['controlled-records.json','counterfactual-results.json'],'result':'All 48 elementary qualifying choices; two non-elementary choices in q-72850 are rejected.'},{'case':'Delivered cases','sample_refs':['stage-coverage.json','delivery/accepted.json','sampling-domain.json'],'result':'182/197 audited records survive, removing source duplicates and repeated controls; all 48 eligible operation roles remain.'},{'case':'Exact runner batch','sample_refs':['runner-batch.json','batch-delivery/accepted.json','shortcut-results.json'],'result':'5/5 survive, with distinct mathematical records, two operation types and four authored answer positions; no fixed slot or fixed-type action solves all five.'}],'counterfactuals':[{'kind':'relevant','change':'Hold A, full answer bank and row mapping fixed; change target between R3:=R3-2R1 and R3:=1/5 R3 in q-130087. Both change the same row. Repeat eligible-target panels for all ten banks.','expected':'Target B, explanation, accepted operation and rejected former operation follow the relevant change.','observed':'Exact Fraction execution and native grading confirm each changed key and reject every other choice. Actual UI shows both target matrices and matching final operations. All ten panels have distinct keys and targets.','status':'passed','justification':'Canonical e-4695 requires comparing the target entries after locating changed rows; unchanged-row structure alone cannot decide scaling versus addition.','sample_refs':['controlled-records.json','counterfactual-results.json','native-input.json','native-results.json','render/input.json','render-inspection.json']},{'kind':'irrelevant','change':'For a scaling question, alter one entry of an unchanged row equally in A and B, keeping the scaled row and operation fixed.','expected':'Same operation remains the unique accepted choice; prompt and solution reflect the irrelevant row edit.','observed':'Seven bank panels preserve the operation. Fraction checks and native all-choice grading pass. q-130087 rendered pair changes first-row 5 to 6 while R3:=1/5 R3 remains the correct response.','status':'passed','justification':'Scaling a row does not depend on entries in other rows, by tutorial 3150’s definition.','sample_refs':['controlled-records.json','counterfactual-results.json','native-results.json','render/input.json','render-inspection.json']}],'shortcut_probes':probes,'delivery':{'stages_examined':['Generator construction and rejection/resampling','Generator mathematical fingerprint deduplication','Shared requested-difficulty filtering and stable identity normalization','Captured-inventory and within-batch deduplication','Read-only reproduction of difficulty weights and fresh-candidate selection','Actual UI answer ordering'],'sample_refs':['resampling-results.json','rejection-witness.json','rejection-witness-records.json','delivery/delivery.json','batch-delivery/delivery.json','stage-coverage.json','selection-results.json','action-shortcut-results.json'],'result':'Fresh seed 694821 returns 60/60 proposals; explicit identity-swap rejection and seed 429 demonstrate resampling to a full five-record batch. Shared publication rules retain all 48 audited roles and all five runner records at captured basis 5359. With any positive configured moderate weight, all delivered moderate candidates remain selectable uniformly after freshness exclusions. Unconfigured lowest-entity fallback and zero-weight behavior examined separately.'},'limitations':['No finite audit proves absence of every incidental shortcut.','Captured inventory basis 5359 contains only twelve original questions; none is relabeled as generated. Live later inventory can differ.','No live learner history, policy weights, task IDs or future generated entity IDs were supplied. Selection tests use actual rules on explicit provisional pools and report conditional conclusions.','q-20240 and q-20389 lack captured keys, worked solutions and ratings; canonical e-4695 lacks an answer field. Those missing artifacts are not invented or certified.','Numeric matrix variation is bounded to one nonzero-entry perturbation with source signs/zero patterns preserved. This review certifies the tested source-bank skill scope, not broad arbitrary-matrix mastery.']}
 # Schema plus path references, no silent omissions.
 schema=load(REPO/'generate/pipeline/pedagogical-variation.schema.json')
 try:
  import jsonschema
  jsonschema.validate(pedagogy,schema);schema_method='jsonschema.validate'
 except ModuleNotFoundError:
  # Minimal recursive enforcement of the supplied schema, covering its used keywords.
  def valid(v,s):
   if 'enum' in s:assert v in s['enum']
   t=s.get('type');types={'object':dict,'array':list,'string':str,'integer':int,'number':(int,float)}
   if t:assert isinstance(v,types[t])
   if isinstance(v,dict):
    assert set(s.get('required',[]))<=set(v)
    if s.get('additionalProperties') is False:assert set(v)<=set(s['properties'])
    for k,x in v.items():
     if k in s.get('properties',{}):valid(x,s['properties'][k])
   if isinstance(v,list):
    assert len(v)>=s.get('minItems',0)
    for x in v:valid(x,s.get('items',{}))
   if isinstance(v,str):assert len(v)>=s.get('minLength',0)
   if isinstance(v,(int,float)):
    if 'minimum' in s:assert v>=s['minimum']
    if 'maximum' in s:assert v<=s['maximum']
  valid(pedagogy,schema);schema_method='recursive enforcement of all keywords used by supplied schema'
 def refs(v):
  if isinstance(v,dict):
   for k,x in v.items():
    if k=='sample_refs':
     for p in x:assert not pathlib.Path(p).is_absolute() and (E/p).is_file() and (E/p).stat().st_size>0,p
    else:refs(x)
  elif isinstance(v,list):
   for x in v:refs(x)
 refs(pedagogy);save('pedagogical-variation.json',pedagogy)
 save('scope-results.json',{'passed':True,'source_based_scope':'Single elementary row operation, 3×3 matrix, five-choice radio, moderate arithmetic. No new operators, prerequisite tasks or response requirements.','sample_cases':['boundary-records.json','controlled-records.json','fresh-sample.json','runner-batch.json'],'extension':'Alternative elementary source-bank choices become correct. Noninteger targets from simple rational scaling/addition remain one-step arithmetic supported by tutorial 3150. Two non-elementary replacement distractors never become correct.','restriction_assessment':'Bounded source-bank coefficients and one-entry perturbations conserve workload. Complete banks and all 48 eligible roles survive delivery, so recognizing a bank/sign/zero layout alone cannot fix a qualifying operation. Does not claim unrestricted matrix sampling.'})
